mapper.insert:
INSERT INTO import_job_attempts (job_id, attempt_no, status, started_at, created_at)
SELECT #{jobId}, COALESCE(MAX(attempt_no), 0) + 1, 'RUNNING', #{now}, #{now}
FROM import_job_attempts
WHERE job_id = #{jobId}

mapper.update:
UPDATE import_job_attempts
SET status = 'SUCCEEDED',
    finished_at = #{now}
WHERE job_id = #{jobId}
  AND status = 'RUNNING'

mapper.select:
SELECT COUNT(*)
FROM import_job_attempts a
JOIN import_jobs j ON j.id = a.job_id
WHERE a.job_id = #{jobId}
  AND a.attempt_no = #{attemptNo}
  AND a.status = 'RUNNING'
  AND j.status = 'RUNNING'
  AND j.lease_expires_at IS NOT NULL
  AND j.lease_expires_at > #{now}

SELECT COUNT(*)
FROM import_jobs
WHERE file_path = #{filePath}
   OR error_report_path = #{filePath}
